// Offline Manager - Handles offline functionality and synchronization
class OfflineManager {
  constructor() {
    this.isOnline = navigator.onLine;
    this.syncQueue = [];
    this.listeners = new Set();
    this.lastSyncTime = null;
    this.syncInProgress = false;
    
    this.init();
  }

  init() {
    // Listen for online/offline events
    window.addEventListener('online', this.handleOnline.bind(this));
    window.addEventListener('offline', this.handleOffline.bind(this));
    
    // Register service worker if not already registered
    this.registerServiceWorker();
    
    // Load sync queue from localStorage
    this.loadSyncQueue();
    
    // Start periodic sync check
    this.startPeriodicSync();
  }

  async registerServiceWorker() {
    if ('serviceWorker' in navigator) {
      try {
        const registration = await navigator.serviceWorker.register('/sw.js');
        console.log('OfflineManager: Service Worker registered successfully');
        
        // Listen for service worker updates
        registration.addEventListener('updatefound', () => {
          const newWorker = registration.installing;
          newWorker.addEventListener('statechange', () => {
            if (newWorker.state === 'installed' && navigator.serviceWorker.controller) {
              // New service worker is available
              this.notifyListeners('sw-update-available');
            }
          });
        });
        
        return registration;
      } catch (error) {
        console.error('OfflineManager: Service Worker registration failed:', error);
      }
    }
  }

  handleOnline() {
    console.log('OfflineManager: Device is online');
    this.isOnline = true;
    this.notifyListeners('online');
    
    // Trigger background sync
    this.triggerBackgroundSync();
    
    // Process sync queue
    this.processSyncQueue();
  }

  handleOffline() {
    console.log('OfflineManager: Device is offline');
    this.isOnline = false;
    this.notifyListeners('offline');
  }

  // Add a listener for offline/online events
  addListener(callback) {
    this.listeners.add(callback);
    return () => this.listeners.delete(callback);
  }

  // Notify all listeners of status changes
  notifyListeners(event, data = null) {
    this.listeners.forEach(callback => {
      try {
        callback({ event, data, isOnline: this.isOnline });
      } catch (error) {
        console.error('OfflineManager: Listener error:', error);
      }
    });
  }

  // Queue an operation for later sync
  queueOperation(operation) {
    const queueItem = {
      id: Date.now() + Math.random(),
      timestamp: new Date().toISOString(),
      operation,
      retries: 0,
      maxRetries: 3
    };
    
    this.syncQueue.push(queueItem);
    this.saveSyncQueue();
    
    console.log('OfflineManager: Operation queued for sync:', operation.type);
    
    // Try to sync immediately if online
    if (this.isOnline) {
      this.processSyncQueue();
    }
    
    return queueItem.id;
  }

  // Process the sync queue
  async processSyncQueue() {
    if (this.syncInProgress || !this.isOnline || this.syncQueue.length === 0) {
      return;
    }

    this.syncInProgress = true;
    this.notifyListeners('sync-start');

    console.log(`OfflineManager: Processing ${this.syncQueue.length} queued operations`);

    const failedOperations = [];

    for (const item of [...this.syncQueue]) {
      try {
        await this.executeOperation(item.operation);
        
        // Remove successful operation from queue
        this.syncQueue = this.syncQueue.filter(op => op.id !== item.id);
        console.log('OfflineManager: Operation synced successfully:', item.operation.type);
        
      } catch (error) {
        console.error('OfflineManager: Operation sync failed:', error);
        
        item.retries++;
        if (item.retries >= item.maxRetries) {
          // Remove failed operation after max retries
          this.syncQueue = this.syncQueue.filter(op => op.id !== item.id);
          failedOperations.push(item);
        }
      }
    }

    this.saveSyncQueue();
    this.lastSyncTime = new Date();
    this.syncInProgress = false;

    this.notifyListeners('sync-complete', {
      synced: this.syncQueue.length === 0,
      failed: failedOperations.length,
      remaining: this.syncQueue.length
    });
  }

  // Execute a queued operation
  async executeOperation(operation) {
    const { type, data, endpoint, method = 'POST' } = operation;

    switch (type) {
      case 'api-call':
        return await this.makeAPICall(endpoint, method, data);
      
      case 'database-update':
        return await this.updateDatabase(data);
      
      case 'file-upload':
        return await this.uploadFile(data);
      
      default:
        throw new Error(`Unknown operation type: ${type}`);
    }
  }

  // Make API call
  async makeAPICall(endpoint, method, data) {
    const response = await fetch(endpoint, {
      method,
      headers: {
        'Content-Type': 'application/json',
      },
      body: data ? JSON.stringify(data) : undefined
    });

    if (!response.ok) {
      throw new Error(`API call failed: ${response.status} ${response.statusText}`);
    }

    return await response.json();
  }

  // Update database
  async updateDatabase(data) {
    // This would integrate with your database operations
    console.log('OfflineManager: Database update:', data);
    return Promise.resolve();
  }

  // Upload file
  async uploadFile(data) {
    const formData = new FormData();
    formData.append('file', data.file);
    
    const response = await fetch(data.endpoint, {
      method: 'POST',
      body: formData
    });

    if (!response.ok) {
      throw new Error(`File upload failed: ${response.status}`);
    }

    return await response.json();
  }

  // Trigger background sync via service worker
  async triggerBackgroundSync() {
    if ('serviceWorker' in navigator && 'sync' in window.ServiceWorkerRegistration.prototype) {
      try {
        const registration = await navigator.serviceWorker.ready;
        await registration.sync.register('background-sync');
        console.log('OfflineManager: Background sync registered');
      } catch (error) {
        console.error('OfflineManager: Background sync registration failed:', error);
      }
    }
  }

  // Start periodic sync check
  startPeriodicSync() {
    setInterval(() => {
      if (this.isOnline && this.syncQueue.length > 0) {
        this.processSyncQueue();
      }
    }, 30000); // Check every 30 seconds
  }

  // Save sync queue to localStorage
  saveSyncQueue() {
    try {
      localStorage.setItem('offline-sync-queue', JSON.stringify(this.syncQueue));
    } catch (error) {
      console.error('OfflineManager: Failed to save sync queue:', error);
    }
  }

  // Load sync queue from localStorage
  loadSyncQueue() {
    try {
      const saved = localStorage.getItem('offline-sync-queue');
      if (saved) {
        this.syncQueue = JSON.parse(saved);
        console.log(`OfflineManager: Loaded ${this.syncQueue.length} queued operations`);
      }
    } catch (error) {
      console.error('OfflineManager: Failed to load sync queue:', error);
      this.syncQueue = [];
    }
  }

  // Get current status
  getStatus() {
    return {
      isOnline: this.isOnline,
      queueLength: this.syncQueue.length,
      lastSyncTime: this.lastSyncTime,
      syncInProgress: this.syncInProgress
    };
  }

  // Clear sync queue
  clearSyncQueue() {
    this.syncQueue = [];
    this.saveSyncQueue();
    this.notifyListeners('queue-cleared');
  }

  // Force sync now
  async forcSync() {
    if (this.isOnline) {
      await this.processSyncQueue();
    } else {
      throw new Error('Cannot sync while offline');
    }
  }

  // Check if feature is available offline
  isFeatureAvailableOffline(feature) {
    const offlineFeatures = [
      'view-data',
      'add-initiative',
      'edit-initiative',
      'add-award-point',
      'edit-award-point',
      'view-reports',
      'export-data'
    ];
    
    return offlineFeatures.includes(feature);
  }

  // Get cache status
  async getCacheStatus() {
    if ('caches' in window) {
      try {
        const cacheNames = await caches.keys();
        const cacheInfo = await Promise.all(
          cacheNames.map(async name => {
            const cache = await caches.open(name);
            const keys = await cache.keys();
            return { name, count: keys.length };
          })
        );
        
        return {
          available: true,
          caches: cacheInfo,
          totalCaches: cacheNames.length
        };
      } catch (error) {
        return { available: false, error: error.message };
      }
    }
    
    return { available: false, error: 'Cache API not supported' };
  }

  // Clear all caches
  async clearCaches() {
    if ('caches' in window) {
      const cacheNames = await caches.keys();
      await Promise.all(cacheNames.map(name => caches.delete(name)));
      console.log('OfflineManager: All caches cleared');
      this.notifyListeners('caches-cleared');
    }
  }
}

// Create singleton instance
export const offlineManager = new OfflineManager();

// Export class for testing
export { OfflineManager };

// Utility functions
export const isOnline = () => offlineManager.isOnline;
export const queueForSync = (operation) => offlineManager.queueOperation(operation);
export const addOfflineListener = (callback) => offlineManager.addListener(callback);
export const getOfflineStatus = () => offlineManager.getStatus();
export const isFeatureAvailableOffline = (feature) => offlineManager.isFeatureAvailableOffline(feature);
